Here is the commit message:
net/sched: cls_u32: use skb_header_pointer_careful()

skb_header_pointer() does not fully validate negative @offset values.

Use skb_header_pointer_careful() instead.

GangMin Kim provided a report and a repro fooling u32_classify():

BUG: KASAN: slab-out-of-bounds in u32_classify+0x1180/0x11b0
net/sched/cls_u32.c:221

Fixes: fbc2e7d9cf49 ("cls_u32: use skb_header_pointer() to dereference data safely")
Reported-by: GangMin Kim <km.kim1503@gmail.com>
Closes: https://lore.kernel.org/netdev/CANn89iJkyUZ=mAzLzC4GdcAgLuPnUoivdLaOs6B9rq5_erj76w@mail.gmail.com/T/
Signed-off-by: Eric Dumazet <edumazet@google.com>
Link: https://patch.msgid.link/20260128141539.3404400-3-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function skb_header_pointer() does not fully validate negative offset values, allowing an attacker to craft packets that cause u32_classify() to access memory out of bounds via a negative offset, leading to a slab-out-of-bounds bug.

Here is the patch:

 TC_INDIRECT_SCOPE int u32_classify(struct sk_buff *skb,
 				   const struct tcf_proto *tp,
 				   struct tcf_result *res)
 {
 	struct {
 		struct tc_u_knode *knode;
 		unsigned int	  off;
 	} stack[TC_U32_MAXDEPTH];

 	struct tc_u_hnode *ht = rcu_dereference_bh(tp->root);
 	unsigned int off = skb_network_offset(skb);
 	struct tc_u_knode *n;
 	int sdepth = 0;
 	int off2 = 0;
 	int sel = 0;
 #ifdef CONFIG_CLS_U32_PERF
 	int j;
 #endif
 	int i, r;

 next_ht:
 	n = rcu_dereference_bh(ht->ht[sel]);

 next_knode:
 	if (n) {
 		struct tc_u32_key *key = n->sel.keys;

 #ifdef CONFIG_CLS_U32_PERF
 		__this_cpu_inc(n->pf->rcnt);
 		j = 0;
 #endif

 		if (tc_skip_sw(n->flags)) {
 			n = rcu_dereference_bh(n->next);
 			goto next_knode;
 		}

 #ifdef CONFIG_CLS_U32_MARK
 		if ((skb->mark & n->mask) != n->val) {
 			n = rcu_dereference_bh(n->next);
 			goto next_knode;
 		} else {
 			__this_cpu_inc(*n->pcpu_success);
 		}
 #endif

 		for (i = n->sel.nkeys; i > 0; i--, key++) {
 			int toff = off + key->off + (off2 & key->offmask);
 			__be32 *data, hdata;

-			if (skb_headroom(skb) + toff > INT_MAX)
-				goto out;
-
-			data = skb_header_pointer(skb, toff, 4, &hdata);
+			data = skb_header_pointer_careful(skb, toff, 4,
+							  &hdata);
 			if (!data)
 				goto out;
 			if ((*data ^ key->val) & key->mask) {
 				n = rcu_dereference_bh(n->next);
 				goto next_knode;
 			}
 #ifdef CONFIG_CLS_U32_PERF
 			__this_cpu_inc(n->pf->kcnts[j]);
 			j++;
 #endif
 		}

 		ht = rcu_dereference_bh(n->ht_down);
 		if (!ht) {
 check_terminal:
 			if (n->sel.flags & TC_U32_TERMINAL) {

 				*res = n->res;
 				if (!tcf_match_indev(skb, n->ifindex)) {
 					n = rcu_dereference_bh(n->next);
 					goto next_knode;
 				}
 #ifdef CONFIG_CLS_U32_PERF
 				__this_cpu_inc(n->pf->rhit);
 #endif
 				r = tcf_exts_exec(skb, &n->exts, res);
 				if (r < 0) {
 					n = rcu_dereference_bh(n->next);
 					goto next_knode;
 				}

 				return r;
 			}
 			n = rcu_dereference_bh(n->next);
 			goto next_knode;
 		}

 		/* PUSH */
 		if (sdepth >= TC_U32_MAXDEPTH)
 			goto deadloop;
 		stack[sdepth].knode = n;
 		stack[sdepth].off = off;
 		sdepth++;

 		ht = rcu_dereference_bh(n->ht_down);
 		sel = 0;
 		if (ht->divisor) {
 			__be32 *data, hdata;

-			data = skb_header_pointer(skb, off + n->sel.hoff, 4,
-						  &hdata);
+			data = skb_header_pointer_careful(skb,
+							  off + n->sel.hoff,
+							  4, &hdata);
 			if (!data)
 				goto out;
 			sel = ht->divisor & u32_hash_fold(*data, &n->sel,
 							  n->fshift);
 		}
 		if (!(n->sel.flags & (TC_U32_VAROFFSET | TC_U32_OFFSET | TC_U32_EAT)))
 			goto next_ht;

 		if (n->sel.flags & (TC_U32_OFFSET | TC_U32_VAROFFSET)) {
 			off2 = n->sel.off + 3;
 			if (n->sel.flags & TC_U32_VAROFFSET) {
 				__be16 *data, hdata;

-				data = skb_header_pointer(skb,
+				data = skb_header_pointer_careful(skb,
 							  off + n->sel.offoff,
 							  2, &hdata);
 				if (!data)
 					goto out;
 				off2 += ntohs(n->sel.offmask & *data) >>
 					n->sel.offshift;
 			}
 			off2 &= ~3;
 		}
 		if (n->sel.flags & TC_U32_EAT) {
 			off += off2;
 			off2 = 0;
 		}

 		if (off < skb->len)
 			goto next_ht;
 	}

 	/* POP */
 	if (sdepth--) {
 		n = stack[sdepth].knode;
 		ht = rcu_dereference_bh(n->ht_up);
 		off = stack[sdepth].off;
 		goto check_terminal;
 	}
 out:
 	return -1;

 deadloop:
 	net_warn_ratelimited("cls_u32: dead loop\n");
 	return -1;
 }



